D=Path(__file__).parent;E=D/'evidence'
def meta(n):return json.loads((E/(n+'.json')).read_text())
def source(url,claim,path=None):return dict(url=url,claim=claim,evidence_path=path)
def rob(n,url):
 m=meta(n+'-robots');r=robots_decision(E/(n+'-robots.json'),url)
 return dict(url=m['url'],status=m['status'],checked_at_utc=m['checked_at_utc'],evidence_path=m['metadata_path'],decision=r['decision'],note=r['note'])
def query(n,text,count,note,chain):
 m=meta(n)
 return dict(text=text,method=m['method'],url=m['url'],payload=m['payload'],checked_at_utc=m['checked_at_utc'],http_status=m['status'],effective_url=m['effective_url'],result_count=count,count_note=note,match_type='exact_title',evidence_path=m['evidence_path'],metadata_path=m['metadata_path'],request_chain=chain)
def size(value,unit,url,path,quality,note,date='undated; checked 2026-11-15'):
 return dict(value=value,unit=unit,date=date,source_url=url,evidence_path=path,quality=quality,note=note)
def book(title,author,id,url,isbn,holdings,path):return dict(title=title,author=author,record_id=id,record_url=url,isbn=isbn,holdings=holdings,evidence_path=path)
