 body=m.get('text','');reason=r['note']
 if 'BUNKERWEB' in body:reason='Robots request redirected to BunkerWeb proof-of-work challenge; not a fallback or policy clearance. No search or challenge interaction.'
 elif 'Cloudflare' in body:reason='Robots returned Cloudflare explicit access-denied page, HTTP403. No automated query.'
 elif r['decision']=='restricted':reason='Robots explicitly excludes the intended public catalogue/search path; no search request.'
 elif 'Acceso Restringido' in body:reason='Robots HTTP500 is an explicit institutional security block, not policy clearance; no search.'
 elif 'MANTENIMIENTO' in body:reason='Robots HTTP503 maintenance page; unresolved, no search.'
 else:reason+='; '+m.get('error','')
 blocked.append(dict(name=name,url=url,reason=reason,evidence_path=m['metadata_path'],robots_decision=r['decision']))
 audit.append(dict(name=name,url=url,robots_metadata=m['metadata_path'],**r))
